{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <link rel="stylesheet" href="assets/css/styles.css">
  <meta name="description" content="A membership-based aromatherapy studio offering guided short practices, custom blends, and safe scent education that may support everyday wellbeing.">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" aria-label="Main navigation">
        <ul>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="blends.html">Blends Lab</a></li>
          <li><a href="shop.html">Emporium</a></li>
          <li><a href="pricing.html">Memberships</a></li>
          <li><a href="about.html">Story</a></li>
          <li><a href="book.html">Sessions</a></li>
          <li><a href="contact.html">Connect</a></li>
        </ul>
      </nav>
      <a class="primary-btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="wrap hero-grid">
        <div>
          <h1>Small scent practices that may support steadiness</h1>
          <p class="lead">Short, membership-led scent guidance with hands-on blend-making and gentle practices for daily reset.</p>
          <div class="hero-ctas">
            <a class="btn" href="pricing.html">Explore Memberships</a>
            <button id="tryNowHero" class="btn alt">Try a 3-minute practice</button>
          </div>
        </div>
        <aside class="card">
          <h3>New member offer</h3>
          <p>Monthly lab access + 10% Emporium credit for members. Learn more on the Memberships page.</p>
          <a href="pricing.html" class="small-link">See plans</a>
        </aside>
      </div>
    </section>

    <!-- Blend builder (diagnostic) -->
    <section id="blend-builder" class="section">
      <div class="wrap">
        <h2>Blends Lab — choose a vibe, we'll suggest a safe mix</h2>
        <p class="muted">Pick a direction, get a simple recipe and dilution guidance. This is educational and non-medical; always patch test.</p>

        <div class="grid">
          <form id="blendForm" class="blend-form" aria-label="Blend builder">
            <label for="vibe">Desired vibe</label>
            <select id="vibe" name="vibe">
              <option value="calm">Calm</option>
              <option value="focus">Focus</option>
              <option value="sleep">Sleep</option>
              <option value="uplift">Uplift</option>
            </select>

            <label for="drops">Bottle size (ml)</label>
            <select id="drops" name="drops">
              <option value="10">10 ml</option>
              <option value="15">15 ml</option>
              <option value="30" selected>30 ml</option>
              <option value="50">50 ml</option>
            </select>

            <label for="audience">Who will use this?</label>
            <select id="audience" name="audience">
              <option value="adult">Adult (typical)</option>
              <option value="sensitive">Sensitive skin</option>
              <option value="child">Child (6–12)</option>
              <option value="pregnant">Pregnant / breastfeeding (review safety)</option>
              <option value="pet">For use around pets (caution)</option>
            </select>

            <button type="button" id="makeBlend" class="btn">Create blend</button>
          </form>

          <div class="result" id="blendResult" aria-live="polite">
            <h3>Your blend</h3>
            <div id="blendCard" class="blend-card empty">
              <p class="muted">Select options and press "Create blend" to see a sample blend card and dilution guide.</p>
            </div>
          </div>
        </div>

        <details class="faq">
          <summary>Safety & notes</summary>
          <ul>
            <li>All suggestions are educational and not medical advice. Individual reactions vary; consult a professional if needed.</li>
            <li>Patch test: apply one diluted drop to a small skin area and wait 24 hours for irritation.</li>
            <li>Pregnancy & breastfeeding: some oils are not recommended. Please check with a qualified practitioner before using.</li>
            <li>Pets: many essential oils are harmful to animals. Keep blends away from pets and consult a veterinarian for guidance.</li>
          </ul>
        </details>
      </div>
    </section>

    <!-- Plan (membership) -->
    <section class="section alt" id="plan">
      <div class="wrap">
        <h2>Membership rhythm</h2>
        <p class="muted">A rolling membership with monthly lab hours, bite-size classes, and guided scent practices you can borrow from anytime.</p>
        <div class="plans">
          <div class="plan">
            <h3>Seed</h3>
            <p class="price">$9/mo</p>
            <ul>
              <li>Weekly micro-practices</li>
              <li>Members-only blend recipes</li>
            </ul>
            <a href="pricing.html" class="btn small">Join Seed</a>
          </div>
          <div class="plan featured">
            <h3>Root</h3>
            <p class="price">$29/mo</p>
            <ul>
              <li>Monthly live lab</li>
              <li>1:1 blend review/quarter</li>
            </ul>
            <a href="pricing.html" class="btn small">Join Root</a>
          </div>
          <div class="plan">
            <h3>Canopy</h3>
            <p class="price">$79/mo</p>
            <ul>
              <li>Unlimited lab sessions</li>
              <li>Priority booking + Emporium credit</li>
            </ul>
            <a href="pricing.html" class="btn small">Join Canopy</a>
          </div>
        </div>
      </div>
    </section>

    <!-- Micro habits -->
    <section class="section" id="micro_habits">
      <div class="wrap">
        <h2>Micro rituals to practice</h2>
        <ul class="habits">
          <li><strong>3-minute anchor:</strong> Hold inhaler near nose, breathe 4-4-4. Repeat 3x.</li>
          <li><strong>Midday sniff:</strong> A single inhale on a cotton ball to reset sensory attention.</li>
          <li><strong>Evening scent journal:</strong> Note one feeling the aroma may support.</li>
        </ul>
        <button id="tryNowInline" class="btn alt">Try a practice now</button>
      </div>
    </section>

    <!-- Pricing teaser -->
    <section class="section pricing" id="pricing">
      <div class="wrap">
        <h2>Flexible access, membership-first</h2>
        <p class="muted">We center regular short practices rather than one-off fixes. Pricing and details are on the Memberships page.</p>
        <a href="pricing.html" class="btn">View plans</a>
      </div>
    </section>

    <!-- CTA -->
    <section class="section cta">
      <div class="wrap">
        <h2>Start a small scent practice today</h2>
        <p>Memberships include guided practices and a safe blend library you can adapt to your life and context.</p>
        <a class="btn large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

    <!-- FAQ + Contact -->
    <footer class="site-footer">
      <div class="wrap footer-grid">
        <div>
          <h4>Contact</h4>
          <p>{{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          <p>{{CITY}}, {{STATE}}</p>
        </div>
        <div>
          <h4>Quick links</h4>
          <ul>
            <li><a href="about.html">About</a></li>
            <li><a href="book.html">Book a session</a></li>
            <li><a href="contact.html">Connect</a></li>
          </ul>
        </div>
        <div>
          <h4>FAQ — safety highlights</h4>
          <ul>
            <li>Do a patch test before topical use.</li>
            <li>Keep oils out of reach of children and pets.</li>
            <li>Review pregnancy safety and consult a practitioner as needed.</li>
          </ul>
        </div>
      </div>
    </footer>
  </main>

  <!-- Guided practice modal -->
  <aside id="practiceModal" class="modal" aria-hidden="true" role="dialog" aria-label="Guided practice">
    <div class="modal-panel" role="document">
      <button class="close" id="closeModal" aria-label="Close">×</button>
      <div id="practiceContent">
        <h3 id="practiceTitle">3-minute grounding</h3>
        <p id="practiceStep">Prepare: set a quiet 3-minute window. Sit comfortably.</p>
        <div id="practiceControls">
          <button id="startPractice" class="btn">Start</button>
          <button id="nextStep" class="btn alt" style="display:none">Next</button>
        </div>
        <div id="practiceProgress" aria-hidden="true"></div>
      </div>
    </div>
  </aside>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
