{"path":"assets/css/styles.css","content":"/* Core styles for aroma editorial */
:root{
  --bg:#fbfaf8; --muted:#6b6b6b; --accent:#7aa3a1; --accent-2:#d98f6b; --card:#ffffff; --text:#222;
  --max-width:1100px; --radius:10px;
}
*{box-sizing:border-box}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial; margin:0; color:var(--text); background:var(--bg); -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max-width); margin:0 auto; padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.7),transparent); position:sticky; top:0; z-index:20; backdrop-filter: blur(6px)}
.site-header .wrap{display:flex; gap:20px; align-items:center}
.logo{font-weight:700; text-decoration:none; color:var(--text)}
.nav ul{list-style:none; padding:0; margin:0; display:flex; gap:12px}
.nav a{color:var(--muted); text-decoration:none}
.primary-btn{background:var(--accent); color:#fff; padding:8px 14px; border-radius:8px; text-decoration:none}
.hero{padding:60px 0; background-repeat:repeat; border-bottom:1px solid rgba(0,0,0,0.03)}
.hero-grid{display:grid; grid-template-columns:1fr 300px; gap:28px; align-items:start}
.lead{color:var(--muted); font-size:1.05rem}
.card{background:var(--card); box-shadow:0 6px 20px rgba(25,25,25,0.06); padding:18px; border-radius:12px}
.btn{background:var(--accent); color:#fff; padding:10px 14px; border-radius:8px; border:none; cursor:pointer}
.btn.alt{background:transparent; border:1px solid var(--accent); color:var(--accent)}
.btn.small{padding:8px 10px}
.btn.large{padding:14px 20px}
.section{padding:44px 0}
.section.alt{background:linear-gradient(90deg,rgba(250,245,242,0.7),transparent)}
.grid{display:grid; grid-template-columns:360px 1fr; gap:24px; align-items:start}
.blend-form label{display:block; margin-top:10px; font-weight:600}
.blend-form select{width:100%; padding:8px; margin-top:6px; border-radius:8px; border:1px solid #e6e6e6}
.result{background:var(--card); padding:18px; border-radius:12px}
.blend-card{padding:12px; border-radius:10px; background:linear-gradient(180deg,#fff,#fbfbfb); min-height:120px}
.blend-card.empty{display:flex; align-items:center; justify-content:center; color:var(--muted)}
.plans{display:flex; gap:16px; margin-top:18px}
.plan{flex:1; background:var(--card); padding:18px; border-radius:12px; text-align:center}
.plan.featured{box-shadow:0 8px 30px rgba(0,0,0,0.06); transform:translateY(-6px)}
.price{font-size:1.5rem; margin:6px 0}
.habits{list-style:none; padding:0; margin:0}
.habits li{margin:8px 0}
.footer-grid{display:grid; grid-template-columns:1fr 1fr 1fr; gap:18px}
.muted{color:var(--muted)}
.small-link{color:var(--accent-2); text-decoration:none}
.faq{margin-top:16px}
.modal{position:fixed; inset:0; display:none; align-items:center; justify-content:center; background:linear-gradient(rgba(13,16,18,0.45),rgba(13,16,18,0.45));}
.modal[aria-hidden="false"]{display:flex}
.modal-panel{background:var(--card); border-radius:12px; padding:20px; width:90%; max-width:520px; position:relative}
.modal .close{position:absolute; right:12px; top:8px; background:transparent; border:none; font-size:20px}
#practiceProgress{height:8px; background:#eee; border-radius:8px; margin-top:12px; overflow:hidden}
#practiceProgress .bar{height:100%; background:linear-gradient(90deg,var(--accent),var(--accent-2)); width:0%}
/* SVG background sizing for the pattern file */
.hero{background-size:240px 240px}
@media(max-width:820px){.hero-grid{grid-template-columns:1fr} .grid{grid-template-columns:1fr} .wrap{padding:18px}}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Blend builder logic
  const blends = {
    calm: {name:'Calm', oils:[{name:'Lavender',pct:40},{name:'Bergamot',pct:30},{name:'Vetiver',pct:30}]},
    focus: {name:'Focus', oils:[{name:'Rosemary',pct:40},{name:'Peppermint',pct:30},{name:'Lemon',pct:30}]},
    sleep: {name:'Sleep', oils:[{name:'Lavender',pct:50},{name:'Roman Chamomile',pct:25},{name:'Cedarwood',pct:25}]},
    uplift: {name:'Uplift', oils:[{name:'Sweet Orange',pct:50},{name:'Grapefruit',pct:30},{name:'Ylang Ylang',pct:20}]}
  };

  function dropsForVolume(ml, dilutionPercent){
    // Approx: 20 drops = 1 ml
    const mlOfOil = (dilutionPercent/100) * (ml/1); // percent of bottle in ml
    const drops = Math.round(mlOfOil * 20);
    return Math.max(drops,1);
  }

  function dilutionByAudience(audience){
    switch(audience){
      case 'adult': return 2; // percent
      case 'sensitive': return 1;
      case 'child': return 0.5;
      case 'pregnant': return 1; // conservative recommend review
      case 'pet': return 0.5; // for ambient diffusion only; consult vet
      default: return 1.5;
    }
  }

  function buildBlend(vibe, ml, audience){
    const recipe = blends[vibe];
    const dilution = dilutionByAudience(audience);
    const totalDrops = dropsForVolume(ml, dilution);
    // split drops according to oil pct
    const oilDrops = recipe.oils.map(o => ({name:o.name, drops: Math.max(1, Math.round(totalDrops * (o.pct/100)))}));
    return {title:recipe.name, ml, audience, dilution, totalDrops, oilDrops};
  }

  function renderCard(data){
    const card = document.createElement('div');
    card.className = 'blend-card';
    const lines = [];
    lines.push('<strong>'+data.title+' blend</strong>');
    lines.push('<div class="muted">Bottle: '+data.ml+' ml &middot; Approx dilution: '+data.dilution+'% &middot; Total drops: '+data.totalDrops+'</div>');
    lines.push('<ol>');
    data.oilDrops.forEach(o => lines.push('<li>'+o.name+': '+o.drops+' drops</li>'));
    lines.push('</ol>');
    lines.push('<div class="muted">Carrier recommendation: fractionated coconut oil or jojoba to reach the chosen bottle volume. Patch test before topical use.</div>');
    card.innerHTML = lines.join('');
    return card;
  }

  // attach form handlers
  document.addEventListener('DOMContentLoaded', function(){
    const makeBtn = document.getElementById('makeBlend');
    const vibeEl = document.getElementById('vibe');
    const dropsEl = document.getElementById('drops');
    const audEl = document.getElementById('audience');
    const resultWrap = document.getElementById('blendCard');

    makeBtn.addEventListener('click', function(){
      const vibe = vibeEl.value;
      const ml = Number(dropsEl.value);
      const audience = audEl.value;
      const data = buildBlend(vibe, ml, audience);
      resultWrap.classList.remove('empty');
      resultWrap.innerHTML = '';
      resultWrap.appendChild(renderCard(data));
    });

    // Guided practice modal controls
    const modal = document.getElementById('practiceModal');
    const tryBtns = [document.getElementById('tryNowHero'), document.getElementById('tryNowInline')];
    const closeBtn = document.getElementById('closeModal');
    const startBtn = document.getElementById('startPractice');
    const nextBtn = document.getElementById('nextStep');
    const stepText = document.getElementById('practiceStep');
    const title = document.getElementById('practiceTitle');
    const progress = document.getElementById('practiceProgress');

    tryBtns.forEach(b => { if(b) b.addEventListener('click', openModal); });
    closeBtn.addEventListener('click', closeModal);

    let stepIndex = 0; let timer = null;
    const steps = [
      {label:'Ground: Sit tall. Close your eyes if comfortable.', duration:6},
      {label:'Breathe: Inhale 4 seconds, hold 4, exhale 4. Repeat for 3 cycles.', duration:24},
      {label:'Journaling prompt: What do I need right now? Write one short sentence.', duration:30},
      {label:'Set an intention: Choose a tiny action to anchor to this feeling.', duration:10}
    ];

    function openModal(){
      modal.setAttribute('aria-hidden','false');
      stepIndex = 0;
      title.textContent = 'Guided 3-minute practice';
      stepText.textContent = 'Prepare: find a quiet seat and a comfortable posture.';
      startBtn.style.display='inline-block'; nextBtn.style.display='none';
      progress.innerHTML = '<div class="bar" style="width:0%"></div>';
    }
    function closeModal(){
      modal.setAttribute('aria-hidden','true');
      clearInterval(timer);
    }

    function playStep(i){
      const s = steps[i];
      stepText.textContent = s.label;
      // animate progress for the duration
      const bar = progress.querySelector('.bar');
      let elapsed = 0;
      if(timer) clearInterval(timer);
      timer = setInterval(()=>{
        elapsed += 250;
        const pct = Math.min(100, (elapsed/(s.duration*1000))*100);
        if(bar) bar.style.width = pct + '%';
        if(elapsed >= s.duration*1000){
          clearInterval(timer);
          if(i < steps.length-1){ nextBtn.style.display='inline-block'; }
          else { nextBtn.style.display='none'; startBtn.style.display='inline-block'; startBtn.textContent='Done'; }
        }
      },250);
    }

    startBtn.addEventListener('click', function(){
      if(startBtn.textContent === 'Done'){ closeModal(); startBtn.textContent='Start'; return; }
      startBtn.style.display='none';
      nextBtn.style.display='inline-block';
      playStep(stepIndex);
    });

    nextBtn.addEventListener('click', function(){
      stepIndex++;
      if(stepIndex < steps.length){
        playStep(stepIndex);
        nextBtn.style.display='none';
      } else { closeModal(); }
    });

    // Close modal on escape
    document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeModal(); });
  });
})();"} 
